static void check(bool b,const char* text){if(!b)throw std::runtime_error(text);++checks;std::cout<<text<<"=PASS\n";}
template<class F>void wait(F f){for(int n=0;n<5000;++n){if(f())return;std::this_thread::sleep_for(std::chrono::milliseconds(1));}throw std::runtime_error("wait-timeout");}
static QJsonObject page(const library::Document& d,int n=0){QString text="reader page";QJsonArray chars;for(int i=0;i<text.size();++i)chars.append(QJsonObject{{"offset",i},{"text",text.mid(i,1)},{"quad",QJsonArray{i*10,10,i*10+8,10,i*10,25,i*10+8,25}}});return {{"document",d.id},{"revision",d.sha256},{"format",d.format},{"layoutId",d.layout},{"page",n},{"pageId",QString(64,n?'b':'a')},{"text",text},{"chars",chars},{"transform",QJsonArray{1,0,0,1,0,0}}};}
static semantic::Selection selection(const QJsonObject&p){QJsonArray quads;for(int i=0;i<6;++i)quads.append(p["chars"].toArray()[i].toObject()["quad"]);return std::make_shared<const semantic::SelectionSnapshot>(QJsonObject{{"document",p["document"]},{"page",p["page"]},{"pageId",p["pageId"]},{"transform",p["transform"]},{"utf16Range",QJsonArray{0,6}},{"text","reader"},{"quads",quads}});}
// Taps a target the panel painted (as a finger on device would).
static bool tapTarget(notes::Panel& p,int id){auto r=p.targets().rect(id);if(r.empty())return false;return p.finger((r.x0+r.x1)/2,(r.y0+r.y1)/2);}
static void typeInto(notes::Panel& p,const char* text){for(const char* c=text;*c;++c){auto r=p.keyboardTargets().rect(ib::KeyBase+*c);p.finger((r.x0+r.x1)/2,(r.y0+r.y1)/2);}auto d=p.keyboardTargets().rect(ib::KeyDone);p.finger((d.x0+d.x1)/2,(d.y0+d.y1)/2);}
static void settle(notes::Panel& panel){wait([&]{panel.tick();if(!panel.view().error.isEmpty())throw std::runtime_error(panel.view().error.toStdString());return panel.view().ready&&!panel.view().busy&&!panel.unsaved();});}
